<script setup lang="ts">
const {request}=useAdminApi();const rows=ref<any[]>([]);const page=ref(1);const lastPage=ref(1);const specialties=ref<any[]>([]);const error=ref('');const dialog=ref(false);const busy=ref(false);const editId=ref<number|null>(null);const avatar=ref<File|null>(null);
const blank=()=>({name:'',slug:'',bio:'',about:'',degree:'',license_number:'',years_of_experience:0,languages:'فارسی',instagram:'',telegram:'',whatsapp:'',website:'',linkedin:'',meta_title:'',meta_description:'',is_active:true,specialty_ids:[] as number[]});const form=ref(blank());
async function load(){try{const [c,s]=await Promise.all([request<any>(`/admin/counselors?page=${page.value}`),request<any>('/admin/specialties')]);rows.value=c.data;lastPage.value=c.last_page||c.meta?.last_page||1;specialties.value=s.data;}catch(e:any){error.value=e?.data?.message||'خطا';}}
onMounted(load);
function add(){editId.value=null;form.value=blank();avatar.value=null;dialog.value=true;}
function edit(c:any){editId.value=c.id;form.value={...blank(),...c,languages:(c.languages||[]).join('، '),specialty_ids:(c.specialties||[]).map((s:any)=>s.id)};avatar.value=null;dialog.value=true;}
async function save(){busy.value=true;error.value='';try{const fd=new FormData();for(const [k,v] of Object.entries(form.value)){if(k==='languages'){String(v).split(/[,،]/).map(x=>x.trim()).filter(Boolean).forEach((x,i)=>fd.append(`languages[${i}]`,x));}else if(k==='specialty_ids'){(v as number[]).forEach((x,i)=>fd.append(`specialty_ids[${i}]`,String(x)));}else if(k==='is_active')fd.append(k,v?'1':'0');else if(v!==null&&v!==undefined)fd.append(k,String(v));}if(avatar.value)fd.append('avatar',avatar.value);await request(`/admin/counselors${editId.value?'/'+editId.value:''}`,{method:'POST',body:fd});dialog.value=false;await load();}catch(e:any){error.value=JSON.stringify(e?.data?.errors||e?.data?.message||'خطا');}finally{busy.value=false;}}
async function remove(c:any){if(!confirm(`حذف ${c.name}؟`))return;try{await request(`/admin/counselors/${c.id}`,{method:'DELETE'});await load();}catch(e:any){error.value=e?.data?.message||'خطا';}}
</script><template><div dir="rtl"><div class="d-flex justify-space-between mb-5"><h2>مدیریت مشاوران</h2><v-btn color="primary" @click="add">مشاور جدید</v-btn></div><v-alert v-if="error" type="error" class="mb-4">{{error}}</v-alert><v-table><thead><tr><th>نام</th><th>اسلاگ</th><th>تخصص</th><th>فعال</th><th>عملیات</th></tr></thead><tbody><tr v-for="c in rows" :key="c.id"><td>{{c.name}}</td><td>{{c.slug}}</td><td>{{(c.specialties||[]).map((s:any)=>s.title).join('، ')}}</td><td>{{c.is_active?'بله':'خیر'}}</td><td><v-btn size="small" @click="edit(c)">ویرایش</v-btn><v-btn size="small" color="error" @click="remove(c)">حذف</v-btn></td></tr></tbody></v-table><div class="d-flex ga-3 align-center mt-4"><v-btn :disabled="page<=1" @click="page--;load()">قبلی</v-btn><span>صفحه {{page}} از {{lastPage}}</span><v-btn :disabled="page>=lastPage" @click="page++;load()">بعدی</v-btn></div><v-dialog v-model="dialog" max-width="900" scrollable><v-card class="pa-6" dir="rtl"><h3 class="mb-4">{{editId?'ویرایش مشاور':'مشاور جدید'}}</h3><v-row><v-col cols="12" md="6"><v-text-field v-model="form.name" label="نام"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.slug" label="اسلاگ انگلیسی"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.degree" label="مدرک"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.license_number" label="شماره نظام"/></v-col><v-col cols="12" md="6"><v-text-field v-model.number="form.years_of_experience" label="سابقه (سال)" type="number"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.languages" label="زبان‌ها (با ویرگول جدا کنید)"/></v-col><v-col cols="12"><v-select v-model="form.specialty_ids" :items="specialties" item-title="title" item-value="id" label="تخصص‌ها" multiple chips/></v-col><v-col cols="12"><v-textarea v-model="form.bio" label="معرفی کوتاه"/></v-col><v-col cols="12"><v-textarea v-model="form.about" label="درباره مشاور"/></v-col><v-col v-for="key in ['instagram','telegram','whatsapp','website','linkedin','meta_title','meta_description']" :key="key" cols="12" md="6"><v-text-field v-model="(form as any)[key]" :label="key"/></v-col><v-col cols="12"><v-file-input label="تصویر مشاور" accept="image/*" @update:model-value="(v:any)=>avatar=Array.isArray(v)?v[0]:v"/></v-col><v-col cols="12"><v-switch v-model="form.is_active" label="فعال"/></v-col></v-row><div class="d-flex ga-3"><v-btn color="primary" :loading="busy" @click="save">ذخیره</v-btn><v-btn @click="dialog=false">انصراف</v-btn></div></v-card></v-dialog></div></template>
